import{_ as p,a0 as l,w as o,s as r,ao as d,I as t,x as a,a1 as e,A as n}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const x=JSON.parse('{"title":"为什么应该在 Linux 上使用命名管道 | LCTT x X-CMD","titleTemplate":false,"description":"为什么应该在 Linux 上使用命名管道 | LCTT (201802) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"为什么应该在 Linux 上使用命名管道 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"为什么应该在 Linux 上使用命名管道 | LCTT (201802) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201802/20180131 Why you should use named pipes on Linux","title":"为什么应该在 Linux 上使用命名管道","tag":"201802","desc":""},"relativePath":"201802/20180131 Why you should use named pipes on Linux.md","filePath":"[post].md"}'),h={name:"201802/20180131 Why you should use named pipes on Linux.md"};function u(g,s,c,k,b,m){const i=l("Link");return o(),r("div",null,[s[13]||(s[13]=d(`<h1 id="为什么应该在-linux-上使用命名管道" tabindex="-1">为什么应该在 Linux 上使用命名管道 <a class="header-anchor" href="#为什么应该在-linux-上使用命名管道" aria-label="Permalink to “为什么应该在 Linux 上使用命名管道”">​</a></h1><blockquote><p>命名管道并不常用，但是它们为进程间通讯提供了一些有趣的特性。</p></blockquote><p><img src="https://images.techhive.com/images/article/2017/05/blue-1845806_1280-100722976-large.jpg" alt=""></p><p>估计每一位 Linux 使用者都熟悉使用 “|” 符号将数据从一个进程传输到另一个进程的操作。它使用户能简便地从一个命令输出数据到另一个命令，并筛选出想要的数据而无须写脚本进行选择、重新格式化等操作。</p><p>还有另一种管道， 虽然也叫“管道”这个名字却有着非常不同的性质。即您可能尚未使用甚至尚未知晓的——命名管道。</p><p>普通管道与命名管道的一个主要区别就是命名管道是以文件形式实实在在地存在于文件系统中的，没错，它们表现出来就是文件。但是与其它文件不同的是，命名管道文件似乎从来没有文件内容。即使用户往命名管道中写入大量数据，该文件看起来还是空的。</p><h3 id="如何在-linux-上创建命名管道" tabindex="-1">如何在 Linux 上创建命名管道 <a class="header-anchor" href="#如何在-linux-上创建命名管道" aria-label="Permalink to “如何在 Linux 上创建命名管道”">​</a></h3><p>在我们研究这些空空如也的命名管道之前，先追根溯源来看看命名管道是如何被创建的。您应该使用名为 <code>mkfifo</code> 的命令来创建它们。为什么提及“FIFO”？是因为命名管道也被认为是一种 FIFO 特殊文件。术语 “FIFO” 指的是它的<ruby>先进先出<rt>first-in, first-out</rt></ruby>特性。如果你将冰淇淋盛放到碟子中，然后可以品尝它，那么你执行的就是一个LIFO（<ruby>后进先出<rt>last-in, first-out</rt></ruby>操作。如果你通过吸管喝奶昔，那你就在执行一个 FIFO 操作。好，接下来是一个创建命名管道的例子。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ mkfifo mypipe</span></span>
<span class="line"><span>$ ls -l mypipe</span></span>
<span class="line"><span>prw-r-----. 1 shs staff 0 Jan 31 13:59 mypipe</span></span></code></pre></div><p>注意一下特殊的文件类型标记 “p” 以及该文件大小为 0。您可以将重定向数据写入命名管道文件，而文件大小依然为 0。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ echo &quot;Can you read this?&quot; &gt; mypipe</span></span></code></pre></div><p>正如上面所说，敲击回车后似乎什么都没有发生（LCTT 译注：没有返回命令行提示符）。</p><p>另外再开一个终端，查看该命名管道的大小，依旧是 0：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ls -l mypipe</span></span>
<span class="line"><span>prw-r-----. 1 shs staff 0 Jan 31 13:59 mypipe</span></span></code></pre></div><p>也许这有违直觉，用户输入的文本已经进入该命名管道，而你仍然卡在输入端。你或者其他人应该等在输出端，并准备读取放入管道的数据。现在让我们读取看看。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cat mypipe</span></span>
<span class="line"><span>Can you read this?</span></span></code></pre></div><p>一旦被读取之后，管道中的内容就没有了。</p><p>另一种研究命名管道如何工作的方式是通过将放入数据的操作置入后台来执行两个操作（将数据放入管道，而在另外一段读取它）。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ echo &quot;Can you read this?&quot; &gt; mypipe &amp;</span></span>
<span class="line"><span>[1] 79302</span></span>
<span class="line"><span>$ cat mypipe</span></span>
<span class="line"><span>Can you read this?</span></span>
<span class="line"><span>[1]+ Done echo &quot;Can you read this?&quot; &gt; mypipe</span></span></code></pre></div><p>一旦管道被读取或“耗干”，该管道就清空了，尽管我们还能看见它并再次使用。可为什么要费此周折呢？</p><h3 id="为何要使用命名管道" tabindex="-1">为何要使用命名管道？ <a class="header-anchor" href="#为何要使用命名管道" aria-label="Permalink to “为何要使用命名管道？”">​</a></h3><p>命名管道很少被使用的理由似乎很充分。毕竟在 Unix 系统上，总有多种不同的方式完成同样的操作。有多种方式写文件、读文件、清空文件，尽管命名管道比它们来得更高效。</p><p>值得注意的是，命名管道的内容驻留在内存中而不是被写到硬盘上。数据内容只有在输入输出端都打开时才会传送。用户可以在管道的输出端打开之前向管道多次写入。通过使用命名管道，用户可以创建一个进程写入管道并且另外一个进程读取管道的流程，而不用关心协调二者时间上的同步。</p><p>用户可以创建一个单纯等待数据出现在管道输出端的进程，并在拿到输出数据后对其进行操作。下列命令我们采用 <code>tail</code> 来等待数据出现。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ tail -f mypipe</span></span></code></pre></div><p>一旦供给管道数据的进程结束了，我们就可以看到一些输出。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ tail -f mypipe</span></span>
<span class="line"><span>Uranus replicated to WCDC7</span></span>
<span class="line"><span>Saturn replicated to WCDC8</span></span>
<span class="line"><span>Pluto replicated to WCDC9</span></span>
<span class="line"><span>Server replication operation completed</span></span></code></pre></div><p>如果研究一下向命名管道写入的进程，用户也许会惊讶于它的资源消耗之少。在下面的 <code>ps</code> 命令输出中，唯一显著的资源消耗是虚拟内存（VSZ 那一列）。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>ps u -P 80038</span></span>
<span class="line"><span>USER PID %CPU %MEM VSZ RSS TTY STAT START TIME COMMAND</span></span>
<span class="line"><span>shs 80038 0.0 0.0 108488 764 pts/4 S 15:25 0:00 -bash</span></span></code></pre></div><p>命名管道与 Unix/Linux 系统上更常用的管道相比足以不同到拥有另一个名号，但是“管道”确实能反映出它们如何在进程间传送数据的形象，故将称其为“命名管道”还真是恰如其分。也许您在执行操作时就能从这个聪明的 Unix/Linux 特性中获益匪浅呢。</p><hr>`,31)),t("p",null,[s[1]||(s[1]=a("via: ",-1)),e(i,{href:"https://www.networkworld.com/article/3251853/linux/why-use-named-pipes-on-linux.html"},{default:n(()=>[...s[0]||(s[0]=[a("https://www.networkworld.com/article/3251853/linux/why-use-named-pipes-on-linux.html",-1)])]),_:1})]),t("p",null,[s[5]||(s[5]=a("作者：",-1)),e(i,{href:"https://www.networkworld.com/author/Sandra-Henry_Stocker/"},{default:n(()=>[...s[2]||(s[2]=[a("Sandra Henry-Stocker",-1)])]),_:1}),s[6]||(s[6]=a(" 译者：",-1)),e(i,{href:"https://github.com/YPBlib"},{default:n(()=>[...s[3]||(s[3]=[a("YPBlib",-1)])]),_:1}),s[7]||(s[7]=a(" 校对：",-1)),e(i,{href:"https://github.com/wxy"},{default:n(()=>[...s[4]||(s[4]=[a("wxy",-1)])]),_:1})]),t("p",null,[s[10]||(s[10]=a("本文由 ",-1)),e(i,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...s[8]||(s[8]=[a("LCTT",-1)])]),_:1}),s[11]||(s[11]=a(" 原创编译，",-1)),e(i,{href:"https://linux.cn/"},{default:n(()=>[...s[9]||(s[9]=[a("Linux中国",-1)])]),_:1}),s[12]||(s[12]=a(" 荣誉推出",-1))])])}const C=p(h,[["render",u]]);export{x as __pageData,C as default};
